{
  "id": "V030",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "직원들의 휴직 신청 관련 반복 문의에 답하는 목적이 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "규정을 바탕으로 조건과 서류를 설명하고, 답을 확정하기 어려운 문의를 담당자에게 전달함."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "휴직 신청의 적용 조건과 제출 서류가 보존됨."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "직원 질문과 현재 게시된 사내 규정이 입력으로 명시됨."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "조건·서류 설명과 불확실한 문의의 담당자 전달이 보존됨."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "휴직 신청 승인과 인사시스템 정보 변경을 제외함."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "새로운 기능의 추가 없이 원문의 설명 및 전달 범위를 표현함."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "직원은 문의자이고 인사 담당자는 불확실한 문의를 받는 역할로 보존됨."
    }
  ],
  "issues": [],
  "permission_interpretation": "불확실한 문의는 인사 담당자에게 넘기며, 승인이나 인사시스템 정보 변경은 포함하지 않음. 담당자가 매번 승인하거나 별도 조치를 수행한다는 뜻은 아님."
}
